    for r in range(h):
        for c in range(len(grid[r])):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            pts = []
            while q:
                r0, c0 = q.popleft()
                pts.append((r0, c0))
                for nr, nc in ((r0-1,c0),(r0+1,c0),(r0,c0-1),(r0,c0+1)):
                    if (0 <= nr < h and 0 <= nc < len(grid[nr])
                            and grid[nr][nc] == color and (nr,nc) not in seen):
                        seen.add((nr,nc))
                        q.append((nr,nc))
            rs = [p[0] for p in pts]
            cs = [p[1] for p in pts]
            objects.append({'color': color, 'pts': pts, 'r0': min(rs), 'r1': max(rs),
                            'c0': min(cs), 'c1': max(cs)})
    return objects


def _l_shape(obj):
    r0, r1, c0, c1 = obj['r0'], obj['r1'], obj['c0'], obj['c1']
    pts = set(obj['pts'])
    if r0 == r1 or c0 == c1:
        return False
    for rr in (r0, r1):
        for cc in (c0, c1):
            shape = ({(rr, c) for c in range(c0, c1 + 1)} |
                     {(r, cc) for r in range(r0, r1 + 1)})
            if shape == pts:
                return True
    return False


def transform(grid):
    out = [row[:] for row in grid]
    bg = Counter(v for row in out for v in row).most_common(1)[0][0]
    objs = _components(out, bg)
    keys = [o for o in objs if _l_shape(o)]
    if not keys:
        return out
    key = max(keys, key=lambda o: len(o['pts']))
    vertical_arm = key['r1'] - key['r0'] + 1

    # The matching line is the one whose length equals the vertical arm of the
    # reference L. Prefer a horizontal line when there is an exact match.
    matches = []
    for obj in objs:
        if obj is key:
            continue
        height = obj['r1'] - obj['r0'] + 1
        width = obj['c1'] - obj['c0'] + 1
        if height == 1 and width == vertical_arm and len(obj['pts']) == width:
            matches.append((1, obj))
        elif width == 1 and height == vertical_arm and len(obj['pts']) == height:
            matches.append((0, obj))
    if matches:
        target = max(matches, key=lambda x: x[0])[1]
        for r, c in target['pts']:
            out[r][c] = key['color']
    return out
