 "content": "from collections import Counter, deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # Identify the largest non-background L-shaped marker.
    bg = Counter(v for row in out for v in row).most_common(1)[0][0]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = out[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            pts = []
            while q:
                x, y = q.popleft()
                pts.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and out[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            rs = [x for x, _ in pts]
            cs = [y for _, y in pts]
            components.append((color, pts, min(rs), max(rs), min(cs), max(cs)))

    def is_l(comp):
        color, pts, r0, r1, c0, c1 = comp
        p = set(pts)
        if r0 == r1 or c0 == c1:
            return False
        for rr in (r0, r1):
            for cc in (c0, c1):
                shape = {(rr, y) for y in range(c0, c1+1)} | {(x, cc) for x in range(r0, r1+1)}
                if p == shape:
                    return True
        return False

    keys = [co for co in components if is_l(co)]
    if not keys:
        return out
    key = max(keys, key=lambda co: len(co[1]))
    key_color = key[0]
    # The marker's arm dimensions indicate the compact near-rectangular
    # component to recolor; seek a component whose bounding dimensions are
    # approximately half the marker's bounding dimensions.
    kh = key[3] - key[2] + 1
    kw = key[5] - key[4] + 1
    candidates = []
    for co in components:
        if co is key:
            continue
        color, pts, r0, r1, c0, c1 = co
        hh, ww = r1-r0+1, c1-c0+1
        if (abs(hh - (kh+1)//2) <= 1 and abs(ww - (kw+1)//2) <= 1) or (abs(ww - (kh+1)//2) <= 1 and abs(hh - (kw+1)//2) <= 1):
            candidates.append(co)
    if candidates:
        target = max(candidates, key=lambda co: len(co[1]))
        for r, c in target[1]:
            out[r][c] = key_color
    return out


if __name__ == '__main__':
    pass
