def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    bg = Counter(v for row in out for v in row).most_common(1)[0][0]
    seen, comps = set(), []
    for r in range(h):
        for c in range(w):
            color = out[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            pts = []
            while q:
                x, y = q.popleft()
                pts.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and out[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            rs = [x for x, _ in pts]
            cs = [y for _, y in pts]
            comps.append((color, pts, min(rs), max(rs), min(cs), max(cs)))

    def corner(comp):
        color, pts, r0, r1, c0, c1 = comp
        p = set(pts)
        if r0 == r1 or c0 == c1:
            return None
        for rr in (r0, r1):
            for cc in (c0, c1):
                shape = {(rr, y) for y in range(c0, c1+1)} | {(x, cc) for x in range(r0, r1+1)}
                if p == shape:
                    # open quadrant is opposite the corner at (rr, cc)
                    return rr, cc
        return None

    keys = [(comp, corner(comp)) for comp in comps]
    keys = [(comp, elbow) for comp, elbow in keys if elbow is not None]
    if not keys:
        return out
    key, (er, ec) = max(keys, key=lambda item: len(item[0][1]))
    _, _, r0, r1, c0, c1 = key
    # The open quadrant of the L is the rectangle opposite its elbow.
    if er == r0 and ec == c0:
        area = lambda r, c: r > er and c > ec
    elif er == r0 and ec == c1:
        area = lambda r, c: r > er and c < ec
    elif er == r1 and ec == c0:
        area = lambda r, c: r < er and c > ec
    else:
        area = lambda r, c: r < er and c < ec
    candidates = [comp for comp in comps if comp is not key and all(area(r, c) for r, c in comp[1])]
    if candidates:
        target = min(candidates, key=lambda comp: min(abs(r-er)+abs(c-ec) for r, c in comp[1]))
        for r, c in target[1]:
            out[r][c] = key[0]
    return out


if __name__ == '__main__':
