def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    bg = Counter(v for row in out for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = out[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            pts = []
            while q:
                x, y = q.popleft()
                pts.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and out[nx][ny] == color and (nx,ny) not in seen:
                        seen.add((nx,ny)); q.append((nx,ny))
            rs = [x for x,y in pts]; cs = [y for x,y in pts]
            comps.append((color, pts, min(rs), max(rs), min(cs), max(cs)))

    keys = []
    for color, pts, r0, r1, c0, c1 in comps:
        cells = set(pts)
        for hr in (r0, r1):
            for vc in (c0, c1):
                lshape = ({(hr,c) for c in range(c0,c1+1)} |
                          {(r,vc) for r in range(r0,r1+1)})
                if cells == lshape and r1 > r0 and c1 > c0:
                    keys.append((color, r1-r0+1, c1-c0+1, r0, r1, c0, c1))
    if not keys:
        return out
    key_color, kh, kw, kr0, kr1, kc0, kc1 = max(keys, key=lambda k: k[1]*k[2])
    short = min(kh, kw)

    candidates = []
    for color, pts, r0, r1, c0, c1 in comps:
        if color == key_color:
            continue
        hh, ww = r1-r0+1, c1-c0+1
        if len(pts) == short and (hh == 1 or ww == 1):
            # Prefer the isolated segment parallel to the longer key arm.
            parallel = (hh > 1 and kh >= kw) or (ww > 1 and kw > kh)
            candidates.append((parallel, len(pts), color, pts))
    if candidates:
        _, _, _, pts = max(candidates, key=lambda z: (z[0], -min(r for r,c in z[3]), -min(c for r,c in z[3])))
        for r,c in pts:
            out[r][c] = key_color
    return out
